using System.IO;
using System.Linq;
using System.Text;
using System.Diagnostics;
using System.Threading;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using Forms=System.Windows.Forms;
namespace InputAtlas {
public sealed class GamepadWindow : Forms.NativeWindow,IDisposable {
 [StructLayout(LayoutKind.Sequential)] struct RAWDEVICE {public ushort Page,Usage;public uint Flags;public IntPtr Target;}
 [StructLayout(LayoutKind.Sequential)] struct RAWLIST {public IntPtr Device;public uint Type;}
 [StructLayout(LayoutKind.Sequential)] struct RAWHEADER {public uint Type,Size;public IntPtr Device,WParam;}
 [StructLayout(LayoutKind.Sequential)] struct XGAMEPAD {public ushort Buttons;public byte LT,RT;public short LX,LY,RX,RY;}
 [StructLayout(LayoutKind.Sequential)] struct XSTATE {public uint Packet;public XGAMEPAD Pad;}
 [DllImport("user32.dll",SetLastError=true)] static extern bool RegisterRawInputDevices(RAWDEVICE[] devices,uint count,uint size);
 [DllImport("user32.dll",SetLastError=true)] static extern uint GetRawInputData(IntPtr input,uint command,IntPtr data,ref uint size,uint headerSize);
 [DllImport("user32.dll",EntryPoint="GetRawInputDeviceList",SetLastError=true)] static extern uint DeviceCount(IntPtr devices,ref uint count,uint size);
 [DllImport("user32.dll",EntryPoint="GetRawInputDeviceList",SetLastError=true)] static extern uint DeviceList([Out] RAWLIST[] devices,ref uint count,uint size);
 [DllImport("user32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern uint GetRawInputDeviceInfo(IntPtr device,uint command,StringBuilder data,ref uint size);
 [DllImport("user32.dll")] static extern int GetMessageTime();
 [DllImport("xinput1_4.dll",EntryPoint="XInputGetState")] static extern uint XInputGetState(uint index,out XSTATE state);
 readonly Dictionary<IntPtr,PadDevice> sony=new Dictionary<IntPtr,PadDevice>();readonly PadDevice[] xbox=new PadDevice[4];readonly long[] probes=new long[4];readonly string[] xboxFallback=new string[4];readonly XboxIdentityResolver xboxIdentity=new XboxIdentityResolver();bool xboxMetadataDirty;
 readonly PadIdentityRegistry identities;readonly PadSourceRouter sourceRouter=new PadSourceRouter();
 readonly PadDatabase storage;readonly ForegroundResolver foreground=new ForegroundResolver();readonly Forms.Timer input=new Forms.Timer(),clock=new Forms.Timer();readonly Stopwatch elapsed=Stopwatch.StartNew();
 long nextScan,nextFlush,nextStatus,lastPoll;readonly double seconds;readonly string started=DateTime.Now.ToString("o");string mode="both",error="",registrationError="";bool disposed;IntPtr raw;uint capacity=4096;long reports,unknownReports;bool xinputAvailable=true;
 public GamepadWindow(double runSeconds){seconds=runSeconds;NativeRuntime.Configure();identities=new PadIdentityRegistry(Path.Combine(Store.Root,PadIdentityRegistry.FileName));storage=new PadDatabase(Path.Combine(Store.Root,"gamepad.sqlite"));
  CreateHandle(new Forms.CreateParams{Caption="InputAtlas Controller Input",Parent=new IntPtr(-3)});raw=Marshal.AllocHGlobal((int)capacity);
  var registration=new[]{new RAWDEVICE{Page=1,Usage=5,Flags=0x100|0x2000,Target=Handle},new RAWDEVICE{Page=1,Usage=4,Flags=0x100|0x2000,Target=Handle}};
  if(!RegisterRawInputDevices(registration,2,(uint)Marshal.SizeOf(typeof(RAWDEVICE))))registrationError="Raw Input registration failed: "+Marshal.GetLastWin32Error();
  for(int i=0;i<4;i++){xboxFallback[i]=XboxUnknownId(i);xbox[i]=new PadDevice{Id=xboxFallback[i],SourceId="XInput-"+i,Name="Xbox / XInput "+(i+1),Kind="Xbox",InputApi="XInput",Connection="Unknown"};}
  ScanSony();ReadMode();input.Interval=8;input.Tick+=(s,e)=>Poll();clock.Interval=250;clock.Tick+=(s,e)=>Tick();input.Start();clock.Start();Status(false);
 }
 PadDevice Identify(IntPtr device){var identity=HidPadDevices.Read(device);if(identity==null||!identity.SupportedSony)return null;int product=(int)identity.Product;string source=SonyPhysicalIdentity.InterfaceId(identity.Path),physical=SonyPhysicalIdentity.Read(identity);if(physical!=null)identities.Register(source,physical);return new PadDevice{Id=physical??identities.Resolve(source),SourceId=source,Name=product==0x0DF2?"DualSense Edge":product==0x0CE6?"DualSense (DS5)":"DualShock 4",Kind="Sony",InputApi="Raw Input",Product=product,Connection=SonyPhysicalIdentity.Bluetooth(identity)?"Bluetooth":"USB",Connected=true};}
 static string XboxUnknownId(int slot){return "XboxUnconfirmed-"+slot+"-"+Guid.NewGuid().ToString("N").Substring(0,16);}
 void SetXboxIdentity(int slot,string id,string connection,string reason){var d=xbox[slot];if(d.Id!=id){d.Edges.Reset();d.SessionPresses=0;d.LastButton="";d.LastPressAt=DateTime.MinValue;}d.Id=id;d.Connection=connection;d.IdentityReason=reason;d.Name=id.StartsWith("XboxPhysical-")?"Xbox":"Xbox / XInput "+(slot+1);}
 void ScanSony(){try{var all=HidPadDevices.All();var supported=all.Where(p=>p.SupportedSony).ToList();var present=new HashSet<IntPtr>(supported.Select(p=>p.Handle));foreach(var identity in supported){if(sony.ContainsKey(identity.Handle))continue;var d=Identify(identity.Handle);if(d!=null)sony.Add(identity.Handle,d);}foreach(var h in sony.Keys.Where(h=>!present.Contains(h)).ToArray())sony.Remove(h);sourceRouter.ForgetMissing(sony.Values);foreach(var match in xboxIdentity.Scan(all))SetXboxIdentity(match.Slot,match.DeviceId??xboxFallback[match.Slot],match.Connection=="Unknown"?XInputConnection.Read((uint)match.Slot):match.Connection,match.Reason);}catch(Exception ex){error="Device scan: "+ex.Message;for(int i=0;i<4;i++)SetXboxIdentity(i,xboxFallback[i],"Unknown","Device metadata unavailable");}finally{xboxMetadataDirty=false;}}
 void ReadMode(){try{string path=Path.Combine(Store.Root,"controller-settings.json");if(!File.Exists(path))return;var doc=Store.ReadJson(path);string value=Convert.ToString(doc["mode"]);if(value=="auto")value="both";if(!new[]{"both","sony","xbox"}.Contains(value))return;if(value!=mode){mode=value;foreach(var d in sony.Values.Concat(xbox))d.Edges.Reset();}}catch(Exception ex){error="Settings: "+ex.Message;}}
 bool Count(PadDevice d){return PadPolicy.Count(d.Kind,mode,sony.Count>0)&&storage.Pending<10000;}
 void Sample(PadDevice device,PadSample sample){DateTime now=DateTime.Now;if(!PadSourceRouter.Fresh(device,now))device.Edges.Reset();device.LastReport=now;device.Connected=true;device.Counting=Count(device);if(!device.Counting){device.Edges.Reset();return;}if(device.Kind=="Sony"&&!sourceRouter.Accept(device,sony.Values,now)){device.Counting=false;return;}var pressed=device.Edges.Read(sample);if(pressed.Count==0)return;string app=foreground.Read();foreach(string button in pressed){storage.Add(new PadPress{At=now,Device=device.Id,Controller=device.Name,Button=button,App=app});device.SessionPresses++;device.LastButton=button;device.LastPressAt=now;}}
 void Poll(){try{long now=elapsed.ElapsedMilliseconds;if(now-lastPoll>2000){foreach(var d in sony.Values.Concat(xbox))d.Edges.Reset();}lastPoll=now;if(!xinputAvailable)return;if(xboxMetadataDirty){xboxIdentity.Invalidate();ScanSony();}for(int i=0;i<4;i++){if(!xbox[i].Connected&&now<probes[i])continue;XSTATE state;uint result=XInputGetState((uint)i,out state);if(result!=0){if(xbox[i].Connected){xbox[i].Edges.Reset();xboxFallback[i]=XboxUnknownId(i);}xbox[i].Connected=false;xbox[i].Counting=false;probes[i]=now+1500;continue;}if(!xbox[i].Connected){xboxIdentity.Invalidate();ScanSony();}Sample(xbox[i],PadButtons.Xbox(state.Pad.Buttons,state.Pad.LT,state.Pad.RT));}input.Interval=xbox.Any(d=>d.Connected)?8:100;}catch(DllNotFoundException){xinputAvailable=false;error="xinput1_4.dll is unavailable";}catch(Exception ex){error="Xbox input: "+ex.Message;}}
 protected override void WndProc(ref Forms.Message message){try{if(message.Msg==0x00FF)Raw(message.LParam);else if(message.Msg==0x00FE){if(message.WParam.ToInt64()==2)sony.Remove(message.LParam);xboxMetadataDirty=true;nextScan=0;}}catch(Exception ex){error="PS input: "+ex.Message;}finally{base.WndProc(ref message);}}
 void Raw(IntPtr handle){if(unchecked((uint)(Environment.TickCount-GetMessageTime()))>2000){foreach(var staleDevice in sony.Values)staleDevice.Edges.Reset();return;}uint size=0,header=(uint)Marshal.SizeOf(typeof(RAWHEADER));if(GetRawInputData(handle,0x10000003,IntPtr.Zero,ref size,header)==UInt32.MaxValue||size<header+8||size>65536)return;if(size>capacity){Marshal.FreeHGlobal(raw);capacity=size;raw=Marshal.AllocHGlobal((int)capacity);}if(GetRawInputData(handle,0x10000003,raw,ref size,header)==UInt32.MaxValue)return;var h=(RAWHEADER)Marshal.PtrToStructure(raw,typeof(RAWHEADER));if(h.Type!=2)return;PadDevice d;if(!sony.TryGetValue(h.Device,out d)){d=Identify(h.Device);if(d==null)return;sony[h.Device]=d;}uint unit=(uint)Marshal.ReadInt32(raw,(int)header),count=(uint)Marshal.ReadInt32(raw,(int)header+4);if(unit==0||unit>1024||count>1024||(long)unit*count+header+8>size)return;for(int i=0;i<count;i++){var packet=new byte[unit];Marshal.Copy(IntPtr.Add(raw,(int)header+8+i*(int)unit),packet,0,(int)unit);PadSample sample;reports++;d.LastReportId=packet.Length==0?0:packet[0];d.LastReportBytes=packet.Length;if(PadButtons.TrySony(d.Product,packet,out sample)){d.Connection=packet[0]==0x31||packet[0]==0x11||packet.Length==10||packet.Length==78?"Bluetooth":"USB";Sample(d,sample);}else unknownReports++;}}
 void Tick(){try{long now=elapsed.ElapsedMilliseconds;if(now>=nextScan){ScanSony();ReadMode();nextScan=now+2000;}if(now>=nextFlush||storage.Pending>=500){storage.Flush();error="";nextFlush=now+2000;}if(now>=nextStatus){Status(false);nextStatus=now+1000;}if(File.Exists(Path.Combine(Store.Root,"controller.stop"))||(seconds>0&&elapsed.Elapsed.TotalSeconds>=seconds))Forms.Application.ExitThread();}catch(Exception ex){error="Storage/status: "+ex.Message;try{Status(false);}catch{}}}
 void Status(bool stopped){var devices=PadDeviceGroups.Describe(sony.Values.Concat(xbox.Where(d=>d.Connected)),DateTime.Now,stopped,Count);var doc=new{pid=Process.GetCurrentProcess().Id,at=DateTime.Now.ToString("o"),started=started,stopped=stopped,mode=mode,error=error,rawInputError=registrationError,xinputAvailable=xinputAvailable,devices=devices,pending=storage.Pending,sonyReports=reports,unrecognizedSonyReports=unknownReports,pollRequestedMs=8,flushSeconds=2};string file=Path.Combine(Store.Root,"controller-heartbeat.json"),tmp=file+".tmp";File.WriteAllText(tmp,Store.Json.Serialize(doc));if(File.Exists(file))File.Replace(tmp,file,null);else File.Move(tmp,file);}
 public void Dispose(){if(disposed)return;disposed=true;input.Stop();clock.Stop();try{storage.Dispose();}catch(Exception ex){error="Final flush: "+ex.Message;}try{Status(true);}catch{}foreground.Dispose();if(raw!=IntPtr.Zero)Marshal.FreeHGlobal(raw);DestroyHandle();input.Dispose();clock.Dispose();}
}
public static class GamepadEntry {
 [STAThread] public static int Main(string[] args){try{NativeRuntime.Configure();bool owner;using(var mutex=new Mutex(true,NativeRuntime.Name("gamepad-collector"),out owner)){if(!owner)return 0;double seconds=0;if(args.Length==2&&args[0]=="--probe-seconds")seconds=Math.Max(1,Math.Min(600,Double.Parse(args[1],System.Globalization.CultureInfo.InvariantCulture)));using(var window=new GamepadWindow(seconds))Forms.Application.Run();}return 0;}catch(Exception ex){try{File.AppendAllText(Path.Combine(NativeRuntime.Data,"controller-error.log"),DateTime.Now.ToString("o")+" "+ex+Environment.NewLine);}catch{}return 1;}}
}
}
